];"""Minimal bootstrap contract for the Flunk-Out Frenzy curated app.

This module owns the first app-specific API contract for Flunk-Out Frenzy. It
turns the registry-backed curated-app metadata into a stable bootstrap payload
that the bespoke SPA shell can load before any local runtime work exists.
"""

from __future__ import annotations

from pydantic import BaseModel, ConfigDict

from skriptoteket.domain.curated_apps.models import CuratedAppDefinition

FLUNK_OUT_FRENZY_RULESET_ID = "flunk_out_frenzy.prototype_alpha.v1"


class FlunkOutFrenzyFeatureFlags(BaseModel):
    """Serialize the intentionally small app-level feature-flag surface."""

    model_config = ConfigDict(frozen=True)

    audio_enabled: bool
    replay_capture_enabled: bool
    score_submission_enabled: bool


class FlunkOutFrenzyBootstrapResult(BaseModel):
    """Serialize the initial game-shell bootstrap payload."""

    model_config = ConfigDict(frozen=True)

    app_id: str
    title: str
    summary: str
    app_version: str
    ruleset_id: str
    feature_flags: FlunkOutFrenzyFeatureFlags


class GetFlunkOutFrenzyBootstrapHandler:
    """Build the minimal Flunk-Out Frenzy bootstrap response."""

    async def handle(self, *, app: CuratedAppDefinition) -> FlunkOutFrenzyBootstrapResult:
        return FlunkOutFrenzyBootstrapResult(
            app_id=app.app_id,
            title=app.title,
            summary=app.summary,
            app_version=app.app_version,
            ruleset_id=FLUNK_OUT_FRENZY_RULESET_ID,
            feature_flags=FlunkOutFrenzyFeatureFlags(
                audio_enabled=True,
                replay_capture_enabled=False,
                score_submission_enabled=False,
            ),
        )"""Curated-app metadata models and deterministic identities.

Purpose:
  Define the immutable registry metadata used to discover, authorize, and
  launch first-class curated apps inside Skriptoteket.

Relationships:
  - Shared by the in-memory curated app registry and catalog/discovery flows.
  - Provides deterministic `tool_id` generation from stable `app_id` values.
"""

from __future__ import annotations

from enum import StrEnum
from uuid import NAMESPACE_URL, UUID, uuid5

from pydantic import BaseModel, ConfigDict, field_validator, model_validator

from skriptoteket.domain.identity.models import Role

_CURATED_APPS_NAMESPACE = uuid5(NAMESPACE_URL, "skriptoteket.curated_apps")


def curated_app_tool_id(*, app_id: str) -> UUID:
    normalized = app_id.strip()
    if not normalized:
        raise ValueError("app_id is required")
    return uuid5(_CURATED_APPS_NAMESPACE, normalized)


class CuratedAppUiMode(StrEnum):
    GENERIC_OK = "generic_ok"
    BESPOKE_REQUIRED = "bespoke_required"


class CuratedAppPlacement(BaseModel):
    """Where an app appears in Katalog (profession/category browse tree)."""

    model_config = ConfigDict(frozen=True)

    profession_slug: str
    category_slug: str

    @field_validator("profession_slug", "category_slug")
    @classmethod
    def _validate_slug(cls, value: str) -> str:
        normalized = value.strip()
        if not normalized:
            raise ValueError("slug is required")
        if len(normalized) > 64:
            raise ValueError("slug must be 64 characters or less")
        return normalized


class CuratedAppDefinition(BaseModel):
    """Curated app metadata discovered via a registry (ADR-0023)."""

    model_config = ConfigDict(frozen=True)

    app_id: str
    tool_id: UUID
    app_version: str
    ui_mode: CuratedAppUiMode = CuratedAppUiMode.GENERIC_OK
    title: str
    summary: str | None = None
    min_role: Role = Role.USER
    default_favorite: bool = False
    placements: list[CuratedAppPlacement]

    @field_validator("app_id", "app_version", "title")
    @classmethod
    def _validate_required_text(cls, value: str) -> str:
        normalized = value.strip()
        if not normalized:
            raise ValueError("value is required")
        return normalized

    @field_validator("summary")
    @classmethod
    def _normalize_optional_summary(cls, value: str | None) -> str | None:
        if value is None:
            return None
        normalized = value.strip()
        return normalized if normalized else None

    @field_validator("placements")
    @classmethod
    def _validate_placements(cls, value: list[CuratedAppPlacement]) -> list[CuratedAppPlacement]:
        if not value:
            raise ValueError("placements is required")
        return value

    @model_validator(mode="after")
    def _validate_tool_id_matches_app_id(self) -> CuratedAppDefinition:
        expected = curated_app_tool_id(app_id=self.app_id)
        if self.tool_id != expected:
            raise ValueError("tool_id must be derived deterministically from app_id")
        return self

    def matches_placement(self, *, profession_slug: str, category_slug: str) -> bool:
        normalized_profession = profession_slug.strip()
        normalized_category = category_slug.strip()
        return any(
            p.profession_slug == normalized_profession and p.category_slug == normalized_category
            for p in self.placements
        )"""Identity domain models for users, sessions, and registration allowlists.

Purpose:
  Keep framework-agnostic identity state in one place, including the
  allowlist/blocklist records used by registration domain validation.

Relationships:
  - Consumed by application handlers and repository protocols.
  - Mapped from SQLAlchemy models in `skriptoteket.infrastructure.db.models.*`.
"""

from __future__ import annotations

from datetime import datetime
from enum import StrEnum
from typing import Literal
from uuid import UUID

from pydantic import BaseModel, ConfigDict


class Role(StrEnum):
    USER = "user"
    CONTRIBUTOR = "contributor"
    ADMIN = "admin"
    SUPERUSER = "superuser"


class AuthProvider(StrEnum):
    LOCAL = "local"
    HULEEDU = "huleedu"


class OrganizationType(StrEnum):
    KOMMUN = "kommun"
    ENSKILD_HUVUDMAN = "enskild_huvudman"
    GOVERNMENT_AGENCY = "government_agency"
    OTHER = "other"


class AllowedDomain(BaseModel):
    """A root domain allowed for automatic user registration."""

    model_config = ConfigDict(frozen=True, from_attributes=True)

    domain: str  # e.g., "stockholm.se"
    org_type: OrganizationType
    org_name: str
    source: str
    source_ref: str | None = None
    is_active: bool = True
    notes: str | None = None
    created_at: datetime
    updated_at: datetime


class BlockedDomain(BaseModel):
    """A root domain explicitly blocked (e.g., personal email providers)."""

    model_config = ConfigDict(frozen=True, from_attributes=True)

    domain: str  # e.g., "gmail.com"
    reason: str | None = None
    source: str
    source_ref: str | None = None
    is_active: bool = True
    notes: str | None = None
    created_at: datetime
    updated_at: datetime


class User(BaseModel):
    """Identity used across the application.

    For future federation, `external_id` and `auth_provider` are included.
    Authorization (role) remains local to Skriptoteket.
    """

    model_config = ConfigDict(frozen=True, from_attributes=True)

    id: UUID
    email: str
    role: Role
    auth_provider: AuthProvider
    external_id: str | None = None
    is_active: bool = True
    email_verified: bool = False
    failed_login_attempts: int = 0
    locked_until: datetime | None = None
    last_login_at: datetime | None = None
    last_failed_login_at: datetime | None = None
    created_at: datetime
    updated_at: datetime


class UserProfile(BaseModel):
    """User profile data aligned with HuleEdu identity expectations."""

    model_config = ConfigDict(frozen=True, from_attributes=True)

    user_id: UUID
    first_name: str | None = None
    last_name: str | None = None
    display_name: str | None = None
    allow_remote_fallback: bool | None = None
    inline_completion_provider: Literal["local", "external"] | None = None
    locale: str = "sv-SE"
    created_at: datetime
    updated_at: datetime


class UserAuth(BaseModel):
    """Authentication material for login flows (kept separate from general User usage)."""

    model_config = ConfigDict(frozen=True)

    user: User
    password_hash: str | None = None


class Session(BaseModel):
    """Server-side session stored in PostgreSQL."""

    model_config = ConfigDict(frozen=True, from_attributes=True)

    id: UUID
    user_id: UUID
    csrf_token: str
    allow_remote_fallback: bool | None = None
    inline_completion_provider: Literal["local", "external"] | None = None
    created_at: datetime
    expires_at: datetime
    revoked_at: datetime | None = None"""Protocols for the Flunk-Out Frenzy curated app contract.

These protocols keep the bespoke game bootstrap flow protocol-first so the web
layer can depend on abstractions while the application layer owns the payload
shape.
"""

from __future__ import annotations

from typing import Protocol

from skriptoteket.application.curated_apps.flunk_out_frenzy import FlunkOutFrenzyBootstrapResult
from skriptoteket.domain.curated_apps.models import CuratedAppDefinition


class FlunkOutFrenzyBootstrapHandlerProtocol(Protocol):
    """Build the minimal bootstrap payload for the bespoke game shell."""

    async def handle(self, *, app: CuratedAppDefinition) -> FlunkOutFrenzyBootstrapResult: ...---
type: adr
id: ADR-0073
title: "Competitive browser games as bespoke curated apps with official high-score validation"
status: accepted
owners: "agents"
deciders: ["user-lead"]
created: 2026-03-22
links: ["ADR-0023", "ADR-0027", "EPIC-25", "REF-curated-app-flunk-out-frenzy-architecture-and-foundational-code"]
---

## Context

Skriptoteket already supports curated apps as first-class application modules
with bespoke SPA views and app-specific API surfaces.

We now want to introduce a small family of **competitive browser games** that:

- run as signed-in curated apps inside the existing SPA
- remain fun and responsive during live play
- support trusted global high scores over time
- do not force the browser runtime through the generic tool-run/session UI model

The existing curated-app platform contracts are a strong base, but browser games
introduce a new tension:

- live simulation wants a local browser-owned loop
- competition features want durable backend-owned validation and persistence

We need an explicit architecture that keeps those concerns separate from the
start so the first game can ship locally without later rewriting the app family
to add official score support.

## Decision

### 1. Competitive games are bespoke curated apps

Competitive games SHALL be implemented as curated apps with
`ui_mode=bespoke_required`.

They SHALL:

- register in the curated app registry
- render through the SPA app host under `/apps/:appId`
- expose app-specific typed endpoints under `/api/v1/apps/{app_id}/...`

They SHALL NOT use the generic `AppDetailView` or generic tool action renderer
as the primary UX for live play.

### 2. The browser runtime owns live simulation

For game apps, the frontend runtime SHALL own:

- fixed-step simulation
- input processing
- rendering
- audio
- deterministic gameplay rules during a live run

The backend SHALL NOT be the source of truth for frame-by-frame machine state.

`tool_sessions`, `ui_payload`, and generic run-state orchestration MAY still be
used as internal support primitives, but they SHALL NOT be the primary contract
for the live gameplay loop.

### 3. The backend owns durable competition state

The backend SHALL own:

- app bootstrap metadata
- identity and authorization checks
- pending score submissions
- replay metadata and storage references
- official score promotion
- leaderboard queries

This logic SHALL live in a shared backend subsystem for competitive play rather
than being embedded ad hoc inside one game's web router.

### 4. Introduce a shared `competitive_play` bounded context

Skriptoteket SHALL add a reusable backend subsystem responsible for:

- score submission lifecycle (`pending`, `official`, `rejected`)
- replay-backed validation workflows
- leaderboard scoping
- player-facing leaderboard read models

This subsystem SHALL be reusable across future curated game apps.

### 5. Scope official scores by app and ruleset

Score records SHALL include at minimum:

- `app_id`
- `app_version`
- `ruleset_id`
- owner user id
- score value
- replay asset reference or equivalent replay metadata

The design MAY also include `season_id` when needed.

Official leaderboard queries SHALL scope by app and ruleset, and SHALL NOT
merge incompatible runs across rule changes.

### 6. Use a pending-to-official promotion pipeline

The competition flow SHALL be:

1. the browser completes a local run
2. the client submits a score summary plus replay payload/reference
3. the backend stores a **pending** submission
4. replay validation promotes valid submissions to **official**
5. official leaderboards show only promoted scores

Rejected submissions SHALL retain a reason for auditability and user-facing
error handling.

### 7. Storage choice

PostgreSQL SHALL be the source of truth for:

- score submissions
- official scores
- replay metadata
- leaderboard indexes and queries

Redis SHALL be optional and used only as an optimization for:

- cached leaderboard pages
- rate limiting
- live fan-out, if later required

Redis is not a prerequisite for the first local slice or the first trustworthy
leaderboard slice.

### 8. Identity and public display

Competitive games SHALL use the existing Skriptoteket user/session model.

Leaderboards SHALL NOT expose user email addresses.

Initial public display SHOULD use `UserProfile.display_name`; a dedicated public
alias remains a future enhancement if needed.

## Consequences

### Benefits

- Keeps game feel strong by avoiding server-owned live simulation.
- Preserves curated-app architecture instead of inventing a parallel product.
- Makes official high scores trustworthy without forcing high-latency gameplay.
- Creates a reusable competitive-play backend for future game apps.

### Tradeoffs

- Introduces a new shared bounded context that needs clear ownership.
- Requires explicit replay-format and validation-policy decisions.
- Adds product complexity around ruleset/version scope and score lifecycle.

### Risks

- If we let the first game persist too little metadata, later officialization
  may require migration or invalidating early runs.
- If we overfit the shared subsystem to Flunk-Out Frenzy, future games may not
  fit cleanly.
- If we prematurely require Redis/WebSockets, the first slice may become heavier
  than necessary.

### Mitigations

- Reserve `ruleset_id` from the first score-capable slice.
- Keep replay validation and leaderboard logic app-agnostic.
- Ship local play first, then layer pending submission and promotion on top.---
