}/**
 * Howler-backed audio director for Flunk-Out Frenzy.
 *
 * This adapter turns semantic game-effect events into lightweight synthesized
 * cues so the local prototype feels alive without committing to final assets.
 */

import { Howl, Howler } from "howler";

import type { GameEffectEvent } from "../presentation/gameEffectTypes";
import type { RuntimeAudioDirector } from "./audioTypes";

type CueName =
  | "round-started"
  | "flipper-fired"
  | "launch-released"
  | "bumper-hit"
  | "sling-hit"
  | "rollover-lit"
  | "tripwire-crossed"
  | "standup-target-hit"
  | "popup-target-hit"
  | "gate-passed"
  | "late-bank-complete"
  | "bonus-awarded"
  | "jackpot-lit"
  | "jackpot-awarded"
  | "shoot-again-lit"
  | "ball-drained"
  | "game-over";

export class AudioDirector implements RuntimeAudioDirector {
  readonly enabled = true;
  private readonly cues = new Map<CueName, Howl>();
  private readonly previousGlobalMuteState: boolean;

  static async create(): Promise<AudioDirector> {
    return new AudioDirector();
  }

  private constructor() {
    this.previousGlobalMuteState = Howler._muted;
    Howler.autoUnlock = true;

    this.cues.set("round-started", this.createCue(520, 180, 0.12));
    this.cues.set("flipper-fired", this.createCue(220, 52, 0.08, "square"));
    this.cues.set("launch-released", this.createCue(310, 90, 0.09, "triangle"));
    this.cues.set("bumper-hit", this.createCue(660, 120, 0.16));
    this.cues.set("sling-hit", this.createCue(430, 96, 0.1, "triangle"));
    this.cues.set("rollover-lit", this.createCue(570, 76, 0.08, "triangle"));
    this.cues.set("tripwire-crossed", this.createCue(390, 60, 0.07, "triangle"));
    this.cues.set("standup-target-hit", this.createCue(520, 92, 0.09, "square"));
    this.cues.set("popup-target-hit", this.createCue(720, 105, 0.1));
    this.cues.set("gate-passed", this.createCue(470, 55, 0.06, "triangle"));
    this.cues.set("late-bank-complete", this.createCue(880, 240, 0.18));
    this.cues.set("bonus-awarded", this.createCue(760, 210, 0.16, "triangle"));
    this.cues.set("jackpot-lit", this.createCue(940, 120, 0.14));
    this.cues.set("jackpot-awarded", this.createCue(1_060, 280, 0.2));
    this.cues.set("shoot-again-lit", this.createCue(640, 170, 0.14, "square"));
    this.cues.set("ball-drained", this.createCue(180, 240, 0.16, "triangle"));
    this.cues.set("game-over", this.createCue(120, 360, 0.18, "sawtooth"));
  }

  setMuted(muted: boolean): void {
    Howler.mute(muted);
  }

  consumeEffects(effects: GameEffectEvent[]): void {
    for (const effect of effects) {
      switch (effect.type) {
        case "round-started":
          this.playCue("round-started");
          break;
        case "flipper-fired":
          this.playCue("flipper-fired");
          break;
        case "launch-released":
          this.playCue("launch-released");
          break;
        case "bumper-hit":
          this.playCue("bumper-hit");
          break;
        case "sling-hit":
          this.playCue("sling-hit");
          break;
        case "rollover-lit":
          this.playCue("rollover-lit");
          break;
        case "tripwire-crossed":
          this.playCue("tripwire-crossed");
          break;
        case "standup-target-hit":
          this.playCue("standup-target-hit");
          break;
        case "popup-target-hit":
          this.playCue("popup-target-hit");
          break;
        case "gate-passed":
          this.playCue("gate-passed");
          break;
        case "late-bank-complete":
          this.playCue("late-bank-complete");
          break;
        case "bonus-awarded":
          this.playCue("bonus-awarded");
          break;
        case "jackpot-lit":
          this.playCue("jackpot-lit");
          break;
        case "jackpot-awarded":
          this.playCue("jackpot-awarded");
          break;
        case "shoot-again-lit":
          this.playCue("shoot-again-lit");
          break;
        case "ball-drained":
          this.playCue("ball-drained");
          break;
        case "game-over":
          this.playCue("game-over");
          break;
        case "ball-spawned":
          break;
      }
    }
  }

  dispose(): void {
    for (const cue of this.cues.values()) {
      cue.unload();
    }

    this.cues.clear();
    Howler.mute(this.previousGlobalMuteState);
  }

  private createCue(
    frequencyHz: number,
    durationMs: number,
    volume: number,
    wave: OscillatorType = "sine",
  ): Howl {
    return new Howl({
      src: [createToneDataUri(frequencyHz, durationMs, volume, wave)],
      volume,
      preload: true,
    });
  }

  private playCue(name: CueName): void {
    const cue = this.cues.get(name);
    if (!cue) {
      return;
    }

    if (cue.state() !== "loaded") {
      cue.load();
      return;
    }

    cue.play();
  }
}

function createToneDataUri(
  frequencyHz: number,
  durationMs: number,
  volume: number,
  wave: OscillatorType,
): string {
  const sampleRate = 22_050;
  const sampleCount = Math.max(1, Math.floor((sampleRate * durationMs) / 1000));
  const buffer = new ArrayBuffer(44 + sampleCount * 2);
  const view = new DataView(buffer);

  writeAscii(view, 0, "RIFF");
  view.setUint32(4, 36 + sampleCount * 2, true);
  writeAscii(view, 8, "WAVE");
  writeAscii(view, 12, "fmt ");
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true);
  view.setUint16(22, 1, true);
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, sampleRate * 2, true);
  view.setUint16(32, 2, true);
  view.setUint16(34, 16, true);
  writeAscii(view, 36, "data");
  view.setUint32(40, sampleCount * 2, true);

  for (let index = 0; index < sampleCount; index += 1) {
    const t = index / sampleRate;
    const attack = Math.min(index / (sampleCount * 0.08), 1);
    const release = Math.min((sampleCount - index) / (sampleCount * 0.22), 1);
    const envelope = Math.min(attack, release, 1);
    const sample = waveformSample(2 * Math.PI * frequencyHz * t, wave) * envelope * volume;
    view.setInt16(44 + index * 2, sample * 0x7fff, true);
  }

  return `data:audio/wav;base64,${toBase64(new Uint8Array(buffer))}`;
}

function waveformSample(phase: number, wave: OscillatorType): number {
  switch (wave) {
    case "square":
      return Math.sign(Math.sin(phase)) || 1;
    case "triangle":
      return (2 / Math.PI) * Math.asin(Math.sin(phase));
    case "sawtooth":
      return 2 * (phase / (2 * Math.PI) - Math.floor(phase / (2 * Math.PI) + 0.5));
    case "sine":
    default:
      return Math.sin(phase);
  }
}

function writeAscii(view: DataView, offset: number, text: string): void {
  for (let index = 0; index < text.length; index += 1) {
    view.setUint8(offset + index, text.charCodeAt(index));
  }
}

function toBase64(bytes: Uint8Array): string {
  const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
  let output = "";

  for (let index = 0; index < bytes.length; index += 3) {
    const a = bytes[index] ?? 0;
    const b = bytes[index + 1] ?? 0;
    const c = bytes[index + 2] ?? 0;

    const chunk = (a << 16) | (b << 8) | c;

    output += alphabet[(chunk >> 18) & 63];
    output += alphabet[(chunk >> 12) & 63];
    output += index + 1 < bytes.length ? alphabet[(chunk >> 6) & 63] : "=";
    output += index + 2 < bytes.length ? alphabet[chunk & 63] : "=";
  }

  return output;
}/**
 * Prototype-alpha game engine for Flunk-Out Frenzy.
 *
 * This engine composes the Rapier-backed physics world with the pure scoring
 * rules so the runtime can treat the whole table slice as one simulation unit
 * without collapsing the physics/rules boundary.
 */

import type { RuntimeEngine, RuntimeEngineState } from "../core/runtimeEngineTypes";
import type { RuntimeCommand } from "../core/runtimeTypes";
import type { PhysicsSnapshot, MachineEvent } from "../physics/physicsTypes";
import type { GameEffectEvent } from "../presentation/gameEffectTypes";
import { PhysicsWorld } from "../physics/PhysicsWorld";
import { RuleEngine } from "../rules/RuleEngine";
import { PROTOTYPE_ALPHA_TABLE } from "../table/prototypeAlphaTable";
import type { RuleEvent, RuleSnapshot, RuleStepResult } from "../rules/ruleTypes";

export interface PrototypeAlphaPhysicsMachine {
  reset(): void;
  spawnBall(): void;
  removeBall(): void;
  applyCommand(command: RuntimeCommand): void;
  step(dtMs: number): MachineEvent[];
  currentSnapshot(): PhysicsSnapshot;
  dispose(): void;
}

export interface PrototypeAlphaRulesEngine {
  startGame(): RuleSnapshot;
  currentSnapshot(): RuleSnapshot;
  handleMachineEvents(events: MachineEvent[]): RuleStepResult;
}

export class PrototypeAlphaGameEngine implements RuntimeEngine {
  static async create(): Promise<PrototypeAlphaGameEngine> {
    const physics = await PhysicsWorld.create();
    return new PrototypeAlphaGameEngine(physics, new RuleEngine());
  }

  constructor(
    private readonly physics: PrototypeAlphaPhysicsMachine,
    private readonly rules: PrototypeAlphaRulesEngine,
  ) {}

  startGame(): RuntimeEngineState {
    this.rules.startGame();
    this.physics.reset();
    this.physics.spawnBall();
    return this.currentState([
      { type: "round-started" },
      { type: "ball-spawned" },
    ]);
  }

  restartGame(): RuntimeEngineState {
    return this.startGame();
  }

  applyCommand(command: RuntimeCommand): void {
    this.physics.applyCommand(command);
  }

  step(dtMs: number): RuntimeEngineState {
    const machineEvents = this.physics.step(dtMs);
    return this.applyMachineEvents(machineEvents);
  }

  injectMachineEventsForDebug(events: MachineEvent[]): RuntimeEngineState {
    return this.applyMachineEvents(events);
  }

  private applyMachineEvents(machineEvents: MachineEvent[]): RuntimeEngineState {
    const previousRuleSnapshot = this.rules.currentSnapshot();
    const ruleStep = this.rules.handleMachineEvents(machineEvents);
    const drainedBall = machineEvents.some((event) => event.type === "drain-enter");
    const effects = this.machineEventsToEffects(machineEvents, previousRuleSnapshot, ruleStep);

    if (drainedBall) {
      this.physics.removeBall();
    }

    if (ruleStep.shouldRespawnBall) {
      this.physics.spawnBall();
      effects.push({ type: "ball-spawned" });
    }

    if (ruleStep.snapshot.ballLifecycle.roundFinished) {
      effects.push({ type: "game-over", finalScore: ruleStep.snapshot.score });
    }

    return this.currentState(effects);
  }

  currentState(effects: GameEffectEvent[] = []): RuntimeEngineState {
    const physicsSnapshot = this.physics.currentSnapshot();
    const ruleSnapshot = this.rules.currentSnapshot();

    return {
      score: ruleSnapshot.score,
      ballsRemaining: ruleSnapshot.ballLifecycle.ballsRemaining,
      multiplier: ruleSnapshot.multiplier,
      bonus: ruleSnapshot.bonus,
      jackpot: ruleSnapshot.jackpot,
      ballLifecycle: {
        shootAgainLit: ruleSnapshot.ballLifecycle.shootAgainLit,
      },
      roundFinished: ruleSnapshot.ballLifecycle.roundFinished,
      effects,
      view: {
        board: {
          width: PROTOTYPE_ALPHA_TABLE.board.width,
          height: PROTOTYPE_ALPHA_TABLE.board.height,
        },
        ball: physicsSnapshot.ball,
        flippers: physicsSnapshot.flippers,
        rollovers: PROTOTYPE_ALPHA_TABLE.rollovers.map((rollover) => ({
          tag: rollover.tag,
          label: rollover.label,
          x: rollover.x,
          y: rollover.y,
          lit: ruleSnapshot.litLaneTags.includes(rollover.tag),
        })),
      },
    };
  }

  dispose(): void {
    this.physics.dispose();
  }

  private machineEventsToEffects(
    machineEvents: MachineEvent[],
    previousRuleSnapshot: RuleSnapshot,
    ruleStep: RuleStepResult,
  ): GameEffectEvent[] {
    const effects: GameEffectEvent[] = [];

    for (const event of machineEvents) {
      switch (event.type) {
        case "bumper-fired":
          effects.push({ type: "bumper-hit", tag: event.tag });
          break;
        case "sling-fired":
          effects.push({ type: "sling-hit", tag: event.tag, side: event.side });
          break;
        case "rollover-enter": {
          const wasLit = previousRuleSnapshot.litLaneTags.includes(event.tag);
          if (!wasLit) {
            const rollover = PROTOTYPE_ALPHA_TABLE.rollovers.find((item) => item.tag === event.tag);
            effects.push({
              type: "rollover-lit",
              tag: event.tag,
              label: rollover?.label ?? "?",
            });
          }
          break;
        }
        case "tripwire-crossed":
          effects.push({ type: "tripwire-crossed", tag: event.tag });
          break;
        case "standup-target-hit":
          effects.push({ type: "standup-target-hit", tag: event.tag });
          break;
        case "popup-target-hit":
          effects.push({ type: "popup-target-hit", tag: event.tag });
          break;
        case "gate-passed":
          effects.push({ type: "gate-passed", tag: event.tag });
          break;
        case "launcher-released":
          effects.push({ type: "launch-released", chargeActive: true });
          break;
        case "drain-enter":
          effects.push({
            type: "ball-drained",
            ballsRemaining: ruleStep.snapshot.ballLifecycle.ballsRemaining,
          });
          break;
        case "launch-lane-enter":
        case "launcher-fed":
        case "launcher-charged":
        case "ball-captured":
        case "ball-ejected":
        case "ball-saved":
          break;
      }
    }

    effects.push(...ruleStep.ruleEvents.map(mapRuleEventToGameEffect));

    return effects;
  }
}

function mapRuleEventToGameEffect(ruleEvent: RuleEvent): GameEffectEvent {
  switch (ruleEvent.type) {
    case "late-bank-complete":
      return {
        type: "late-bank-complete",
        multiplier: ruleEvent.multiplier,
      };
    case "bonus-awarded":
      return {
        type: "bonus-awarded",
        points: ruleEvent.points,
      };
    case "jackpot-lit":
      return {
        type: "jackpot-lit",
        points: ruleEvent.points,
      };
    case "jackpot-awarded":
      return {
        type: "jackpot-awarded",
        points: ruleEvent.points,
      };
    case "shoot-again-lit":
      return {
        type: "shoot-again-lit",
      };
  }
}/**
 * Flunk-Out Frenzy shell-to-host contracts.
 *
 * These types keep the bespoke route shell decoupled from the browser-owned
 * runtime. The route consumes read-only HUD projections while `GameHost.vue`
 * forwards imperative lifecycle controls into the runtime core.
 */

import type {
  GameHudSnapshot,
  GameSessionStatus,
  RuntimeCommand,
} from "./game/core/runtimeTypes";
import type { MachineEvent } from "./game/physics/physicsTypes";

export type {
  GameHudSnapshot,
  GameSessionStatus,
  GameViewSnapshot,
} from "./game/core/runtimeTypes";

export type GameRuntimeLoadState = "idle" | "loading" | "ready" | "error";

export interface GameHostApi {
  startGame(): Promise<void>;
  pauseGame(): void;
  resumeGame(): void;
  restartGame(): Promise<void>;
  setMuted(muted: boolean): void;
}

export interface GameRuntimeLike {
  mount(hostElement: HTMLElement): void;
  start(): void;
  pause(): void;
  resume(): void;
  restart(): void;
  setMuted(muted: boolean): void;
  enqueueCommand(command: RuntimeCommand): void;
  subscribeHud(listener: (hud: GameHudSnapshot) => void): () => void;
  dispose(): void;
  injectMachineEventsForDebug?(events: MachineEvent[]): void;
}

export interface GameRuntimeFactoryOptions {
  audioEnabled: boolean;
}

export type GameRuntimeFactory = (
  options: GameRuntimeFactoryOptions,
) => Promise<GameRuntimeLike>;

export function labelGameSessionStatus(
  status: GameSessionStatus,
): "Pågående runda" | "Pausad" | "Game over" | "Redo att starta" {
  switch (status) {
    case "running":
      return "Pågående runda";
    case "paused":
      return "Pausad";
    case "game-over":
      return "Game over";
    case "ready":
      return "Redo att starta";
  }
}"""HTTP routes for the Flunk-Out Frenzy curated app.
This router exposes the bespoke app-specific bootstrap contract used by the SPA
shell. It keeps access checks in the web layer and delegates payload building
to the application handler.
"""

from fastapi import APIRouter, Depends

from skriptoteket.application.curated_apps.flunk_out_frenzy import FlunkOutFrenzyBootstrapResult
from skriptoteket.domain.curated_apps.models import CuratedAppDefinition
from skriptoteket.domain.errors import not_found
from skriptoteket.domain.identity.models import User
from skriptoteket.domain.identity.role_guards import require_at_least_role
from skriptoteket.protocols.curated_apps import CuratedAppRegistryProtocol
from skriptoteket.protocols.flunk_out_frenzy import FlunkOutFrenzyBootstrapHandlerProtocol
from skriptoteket.web.auth.api_dependencies import require_user_api
from skriptoteket.web.dishka_dependencies import FromDishka

APP_ID = "games.flunk_out_frenzy"
router = APIRouter(prefix=f"/api/v1/apps/{APP_ID}", tags=["apps", "flunk-out-frenzy"])


def _require_app_access(
    *, registry: CuratedAppRegistryProtocol, user: User
) -> CuratedAppDefinition:
    app = registry.get_by_app_id(app_id=APP_ID)
    if app is None:
        raise not_found("CuratedApp", APP_ID)
    require_at_least_role(user=user, role=app.min_role)
    return app


@router.get("/bootstrap", response_model=FlunkOutFrenzyBootstrapResult)
async def get_bootstrap(
    registry: FromDishka[CuratedAppRegistryProtocol],
    handler: FromDishka[FlunkOutFrenzyBootstrapHandlerProtocol],
    user: User = Depends(require_user_api),
) -> FlunkOutFrenzyBootstrapResult:
    app = _require_app_access(registry=registry, user=user)
    return await handler.handle(app=app)---
type: epic
id: EPIC-25
title: "Curated app family: competitive games foundations and Flunk-Out Frenzy"
status: active
owners: "agents"
created: 2026-03-22
updated: 2026-04-01
outcome: "Signed-in users can open Flunk-Out Frenzy as a bespoke curated app, play a polished local browser-based experience inside the existing Skriptoteket SPA, deepen the local runtime with richer pinball-like mechanics without collapsing architecture boundaries, and retain the backend seams required to add official high scores without rewriting the app contract."
dependencies: ["ADR-0023", "ADR-0027", "ADR-0073"]
---

## Scope

- **Family architecture**: establish the competitive-games curated-app shape so
  future games can reuse the same competition backend seams.
- **Flunk-Out Frenzy app**: introduce the first game as a bespoke curated app
  under the existing app host.
- **Frontend runtime**: keep live simulation browser-owned and isolated from the
  generic tool-run/session UI model.
- **Mechanics fidelity**: deepen the local game runtime with bounded physics,
  table-authoring, and rule seams that can absorb richer device semantics
  without copying a donor engine architecture.
- **Backend substrate**: reserve the models and API contracts needed for pending
  score submission, official score promotion, replay metadata, and leaderboard
  queries.

## Out of scope

- Multiple game apps shipping in the same slice
- Tournament administration
- Social graph or chat
- Mobile-first controls
- Real-time multiplayer
- Redis/WebSocket infrastructure as a hard requirement
- A wholesale native-engine port or emulator path for Flunk-Out Frenzy

## Risks

- The first game could accidentally couple itself to one-off persistence paths.
- A weak replay/score contract could make later official score support expensive
  to add safely.
- The frontend could drift into Vue-owned simulation state if the shell/runtime
  boundary is not enforced.

## Stories

- [x] [ST-25-01: Competitive games substrate and Flunk-Out Frenzy bootstrap contract](../stories/story-25-01-competitive-games-substrate-and-flunk-out-frenzy-bootstrap-contract.md)
- [x] [ST-25-02: Flunk-Out Frenzy local runtime vertical slice](../stories/story-25-02-flunk-out-frenzy-local-runtime-vertical-slice.md)
- [ ] [ST-25-03: Competitive play pending score submission and typed leaderboards](../stories/story-25-03-competitive-play-pending-score-submission-and-typed-leaderboards.md)
- [ ] [ST-25-04: Competitive play replay validation and official score promotion](../stories/story-25-04-competitive-play-replay-validation-and-official-score-promotion.md)
- [ ] [ST-25-05: Flunk-Out Frenzy mechanics-port foundation](../stories/story-25-05-flunk-out-frenzy-mechanics-port-foundation.md)

## Notes

- **First implementation slice**: ST-25-01 and ST-25-02.
- **Planned from the start**: ST-25-03 and ST-25-04 define the competition path
  that the local slice must remain compatible with.
- **Follow-on local depth**: ST-25-05 deepens the browser-local mechanics
  substrate without taking a dependency on pending-score persistence.
- **ST-25-05 execution gate**: `PR-0188` through `PR-0190` form the first
  foundation tranche, `PR-0191` is a formal reassessment and go/no-go
  checkpoint, and only then do the higher-risk mechanics slices begin.
- Cross-cutting sequencing beyond this epic is tracked in
  `docs/reference/ref-competitive-games-cross-cutting-programme.md`.

## Implementation Summary (as of 2026-04-01)

- `ST-25-05` tranche-one foundation (`PR-0188`, `PR-0189`, `PR-0190`) is
  complete: `PhysicsWorld` and `RuleEngine` are decomposed into modular seams,
  machine-event vocabulary is widened, and pure rule-state modules own bonus,
  jackpot, and ball-lifecycle logic.
- `PR-0191` reassessment returned a **GO** decision: the architecture is stable,
  file-size targets are met, and the runtime boundary is verified as ready for
  the higher-fidelity mechanics tranche.

## Implementation Summary (as of 2026-03-23)

- `ST-25-01` shipped the Flunk-Out Frenzy curated-app registration,
  discoverability, bespoke route resolution, and minimal typed bootstrap
  contract.
- `ST-25-02` shipped the immersive game-first shell, runtime/core boundary,
  Rapier-backed prototype-alpha physics/rules, and the first playable local
  Pixi/Howler 3-ball slice with verified pause/restart/mute and route disposal.<script setup lang="ts">
/**
 * Flunk-Out Frenzy shell view.
 *
 * This bespoke route owns the app bootstrap and presents the first viewport as
 * a single game composition. The shell keeps bootstrap/loading/settings logic
 * at the route layer while delegating the future playfield runtime to
 * `GameHost.vue`.
 */

import { computed, onBeforeUnmount, onMounted, ref } from "vue";

import GameHost from "../../components/apps/flunk-out-frenzy/GameHost.vue";
import {
  labelGameSessionStatus,
  type GameHostApi,
  type GameHudSnapshot,
  type GameRuntimeLoadState,
  type GameRuntimeFactory,
} from "../../components/apps/flunk-out-frenzy/gameHostTypes";
import { createInitialHudSnapshot } from "../../components/apps/flunk-out-frenzy/game/core/runtimeTypes";
import { useFlunkOutFrenzyBootstrap } from "./useFlunkOutFrenzyBootstrap";

const props = defineProps<{
  runtimeFactory?: GameRuntimeFactory;
}>();

const { bootstrap, bootstrapError, isBootstrapping, loadBootstrap } = useFlunkOutFrenzyBootstrap();
// These are intentionally temporary reference-art plates until the dedicated
// Flunk-Out Frenzy cabinet art pass lands.
const sceneReferenceUrl = new URL(
  "../../assets/flunk-out-frenzy/reference-cabinet-scene.jpg",
  import.meta.url,
).href;

// The physics board is 600x1200, but the surrounding cabinet frame is wider to
// preserve a believable machine silhouette around the playfield.
const CABINET_FRAME_ASPECT_RATIO = 0.76;
const DESKTOP_BREAKPOINT_PX = 940;
const DESKTOP_SIDE_RAIL_RESERVE_PX = 336;
const DESKTOP_TOP_MARQUEE_RESERVE_PX = 184;
const DESKTOP_BOTTOM_RESERVE_PX = 20;

const gameHost = ref<GameHostApi | null>(null);
const sceneElement = ref<HTMLElement | null>(null);
const isSettingsOpen = ref(false);
const runtimeBootError = ref<string | null>(null);
const runtimeLoadState = ref<GameRuntimeLoadState>("idle");
const runtimeHostKey = ref(0);
const hud = ref<GameHudSnapshot>(createInitialHudSnapshot());
const hostFrame = ref<{
  width: number | null;
  height: number | null;
}>({
  width: null,
  height: null,
});

const featureFlagRows = computed(() => {
  if (!bootstrap.value) {
    return [];
  }

  return [
    {
      label: "Ljudmotor",
      value: bootstrap.value.feature_flags.audio_enabled ? "Aktiv i den lokala spelklienten" : "Avstängd",
    },
    {
      label: "Replay capture",
      value: bootstrap.value.feature_flags.replay_capture_enabled ? "Påslagen" : "Inte med i denna slice",
    },
    {
      label: "Officiella high scores",
      value: bootstrap.value.feature_flags.score_submission_enabled ? "Påslagna" : "Kommer senare",
    },
  ];
});

const sessionStatusLabel = computed(() => {
  return labelGameSessionStatus(hud.value.status);
});

const pauseLabel = computed(() => {
  return hud.value.status === "paused" ? "Fortsätt" : "Pausa";
});

const canPause = computed(() => {
  if (runtimeBootError.value || runtimeLoadState.value !== "ready") {
    return false;
  }

  return hud.value.status === "running" || hud.value.status === "paused";
});

const hostFrameStyle = computed(() => {
  if (hostFrame.value.width === null || hostFrame.value.height === null) {
    return {};
  }

  return {
    width: `${hostFrame.value.width}px`,
    height: `${hostFrame.value.height}px`,
  };
});

const isAudioAvailable = computed(() => bootstrap.value?.feature_flags.audio_enabled ?? true);

const startLabel = computed(() => {
  return runtimeLoadState.value === "loading" ? "Laddar spelmotor…" : "Start";
});

const canStart = computed(() => {
  if (runtimeBootError.value) {
    return false;
  }

  return runtimeLoadState.value !== "loading" && hud.value.status !== "running";
});

const canRestart = computed(() => {
  return !runtimeBootError.value && runtimeLoadState.value === "ready";
});

const canToggleMute = computed(() => {
  return !runtimeBootError.value && isAudioAvailable.value && runtimeLoadState.value === "ready";
});

const muteLabel = computed(() => {
  if (!isAudioAvailable.value) {
    return "Ljud avstängt";
  }

  return hud.value.muted ? "Ljud av" : "Ljud på";
});

function onHudChange(nextHud: GameHudSnapshot): void {
  hud.value = nextHud;
}

function onRuntimeBootError(message: string | null): void {
  runtimeBootError.value = message;

  if (message) {
    runtimeLoadState.value = "error";
    hud.value = createInitialHudSnapshot();
  }
}

function onRuntimeLoadStateChange(nextState: GameRuntimeLoadState): void {
  runtimeLoadState.value = nextState;
}

function onStart(): void {
  if (runtimeBootError.value) {
    return;
  }

  void gameHost.value?.startGame();
}

function onPauseToggle(): void {
  if (!gameHost.value) {
    return;
  }

  if (hud.value.status === "paused") {
    gameHost.value.resumeGame();
    return;
  }

  gameHost.value.pauseGame();
}

function onRestart(): void {
  if (runtimeBootError.value) {
    return;
  }

  void gameHost.value?.restartGame();
}

function onToggleMute(): void {
  if (runtimeBootError.value || !isAudioAvailable.value) {
    return;
  }

  gameHost.value?.setMuted(!hud.value.muted);
}

function retryRuntimeHost(): void {
  runtimeBootError.value = null;
  runtimeLoadState.value = "idle";
  hud.value = createInitialHudSnapshot();
  runtimeHostKey.value += 1;
}

function updateBoardFrame(): void {
  const scene = sceneElement.value;
  if (!scene || typeof window === "undefined") {
    return;
  }

  if (window.innerWidth <= DESKTOP_BREAKPOINT_PX) {
    hostFrame.value = { width: null, height: null };
    return;
  }

  const sceneStyles = window.getComputedStyle(scene);
  const paddingX = parseFloat(sceneStyles.paddingLeft) + parseFloat(sceneStyles.paddingRight);
  const paddingY = parseFloat(sceneStyles.paddingTop) + parseFloat(sceneStyles.paddingBottom);

  const availableWidth = Math.max(
    scene.clientWidth - paddingX - DESKTOP_SIDE_RAIL_RESERVE_PX,
    320,
  );
  const availableHeight = Math.max(
    scene.clientHeight - paddingY - DESKTOP_TOP_MARQUEE_RESERVE_PX - DESKTOP_BOTTOM_RESERVE_PX,
    420,
  );

  const width = Math.floor(
    Math.min(availableWidth, availableHeight * CABINET_FRAME_ASPECT_RATIO),
  );
  const height = Math.floor(width / CABINET_FRAME_ASPECT_RATIO);

  hostFrame.value = { width, height };
}

onMounted(() => {
  updateBoardFrame();
  window.addEventListener("resize", updateBoardFrame);
});

onBeforeUnmount(() => {
  window.removeEventListener("resize", updateBoardFrame);
});
</script>

<template>
  <section class="fof-shell">
    <div class="fof-shell__haze" />

    <div
      v-if="isBootstrapping"
      data-test="bootstrap-loading"
      class="fof-shell__state fof-shell__state--loading"
    >
      <p class="fof-shell__eyebrow">
        Flunk-Out Frenzy
      </p>
      <h1 class="fof-shell__title">
        Laddar kvällspasset…
      </h1>
      <p class="fof-shell__copy">
        Hämtar bootstrap, ruleset och de första spelinställningarna innan vi
        släcker klassrummet och tänder spelmaskinen.
      </p>
    </div>

    <div
      v-else-if="bootstrapError"
      data-test="bootstrap-error"
      class="fof-shell__state fof-shell__state--error"
    >
      <p class="fof-shell__eyebrow">
        Startfel
      </p>
      <h1 class="fof-shell__title">
        Flunk-Out Frenzy kunde inte starta
      </h1>
      <p class="fof-shell__copy">
        {{ bootstrapError }}
      </p>
      <button
        class="fof-action fof-action--primary"
        type="button"
        @click="loadBootstrap"
      >
        Försök igen
      </button>
    </div>

    <div
      v-else-if="bootstrap"
      data-test="bootstrap-ready"
      class="fof-ready"
    >
      <div
        ref="sceneElement"
        class="fof-machine-scene"
        :style="{
          '--fof-scene-image': `url(${sceneReferenceUrl})`,
          '--fof-cabinet-aspect-ratio': String(CABINET_FRAME_ASPECT_RATIO),
        }"
      >
        <header class="fof-marquee">
          <p class="fof-marquee__eyebrow">
            Prototype alpha
          </p>
          <h1 class="fof-marquee__title">
            {{ bootstrap.title }}
          </h1>
          <p class="fof-marquee__summary">
            {{ bootstrap.summary }}
          </p>
        </header>

        <aside class="fof-status-cluster">
          <div class="fof-plaque">
            <span>Status</span>
            <strong>{{ sessionStatusLabel }}</strong>
          </div>
          <div class="fof-plaque">
            <span>Poäng</span>
            <strong>{{ hud.score.toLocaleString("sv-SE") }}</strong>
          </div>
          <div class="fof-plaque">
            <span>Bollar kvar</span>
            <strong>{{ hud.ballsRemaining }}</strong>
          </div>
          <div class="fof-plaque">
            <span>Multiplikator</span>
            <strong>x{{ hud.multiplier }}</strong>
          </div>
          <div class="fof-plaque">
            <span>Bonus</span>
            <strong>{{ hud.bonus.points.toLocaleString("sv-SE") }}</strong>
          </div>
          <div class="fof-plaque">
            <span>Jackpot</span>
            <strong>
              {{ hud.jackpot.points.toLocaleString("sv-SE") }}
              {{ hud.jackpot.lit ? "• Tänd" : "• Släckt" }}
            </strong>
          </div>
          <div class="fof-plaque">
            <span>Shoot again</span>
            <strong>{{ hud.ballLifecycle.shootAgainLit ? "Tänd" : "Släckt" }}</strong>
          </div>
        </aside>

        <div
          class="fof-machine-scene__host"
          :style="hostFrameStyle"
        >
          <GameHost
            :key="runtimeHostKey"
            ref="gameHost"
            :audio-enabled="bootstrap.feature_flags.audio_enabled"
            :title="bootstrap.title"
            :runtime-factory="props.runtimeFactory"
            @boot-error="onRuntimeBootError"
            @hud-change="onHudChange"
            @load-state-change="onRuntimeLoadStateChange"
          />
        </div>

        <aside class="fof-service-cluster">
          <div
            v-if="runtimeBootError"
            data-test="runtime-route-error"
            class="fof-runtime-error"
          >
            <p class="fof-runtime-error__title">
              Spelmotorn kunde inte starta
            </p>
            <p class="fof-runtime-error__body">
              {{ runtimeBootError }}
            </p>
            <button
              class="fof-action fof-action--primary"
              type="button"
              @click="retryRuntimeHost"
            >
              Försök igen
            </button>
          </div>

          <div class="fof-keyguide">
            <p class="fof-keyguide__eyebrow">
              Kontroller
            </p>
            <div class="fof-keyguide__row">
              <div class="fof-keycaps">
                <span class="fof-keycap">L Shift</span>
                <span class="fof-keycap">R Shift</span>
              </div>
              <span>Flippers</span>
            </div>
            <div class="fof-keyguide__row">
              <div class="fof-keycaps">
                <span class="fof-keycap">Space</span>
              </div>
              <span>Launch</span>
            </div>
          </div>

          <div class="fof-controls">
            <button
              class="fof-action fof-action--primary"
              type="button"
              :disabled="!canStart"
              @click="onStart"
            >
              {{ startLabel }}
            </button>
            <button
              class="fof-action"
              type="button"
              :disabled="!canPause"
              @click="onPauseToggle"
            >
              {{ pauseLabel }}
            </button>
            <button
              class="fof-action"
              type="button"
              :disabled="!canRestart"
              @click="onRestart"
            >
              Starta om
            </button>
            <button
              class="fof-action"
              type="button"
              :disabled="!canToggleMute"
              @click="onToggleMute"
            >
              {{ muteLabel }}
            </button>
          </div>

          <button
            data-test="settings-toggle"
            class="fof-action fof-action--ghost"
            type="button"
            :aria-expanded="isSettingsOpen"
            @click="isSettingsOpen = !isSettingsOpen"
          >
